/**
 * Real-pixel chest-band crop fixture for Architecture C Stage 1g.
 *
 * Provenance [VERIFIED]: lossless RGBA crop from clean still
 * `2aa1a44c-b24a-46bf-890f-13a6fc65b1cc` (hero frame t=0.785,
 * storage `project-references/.../hero_frame_1788460961678.jpg`).
 * Crop window: x 190–639, y 660–760 inclusive (450×101) inside 720×1280.
 *
 * This is NOT a procedural recreation. It carries the Stage 1f live failure
 * modes (shadowed left third that splits from the lit/right navy CC under
 * `isNavyPixel`, crease near x≈279–291 with RGB≈(2,6,17)-class values, and
 * upper-left bright pinstripe). See sibling PNG for a viewable copy.
 */
export const ARCHITECTURE_C_BAND_CROP = {
  cleanStillAssetId: "2aa1a44c-b24a-46bf-890f-13a6fc65b1cc",
  originX: 190,
  originY: 660,
  width: 450,
  height: 101,
  frameW: 720,
  frameH: 1280,
  measuredBandQuadNorm: [
    [0.3, 0.53],
    [0.87, 0.533],
    [0.87, 0.585],
    [0.3, 0.582],
  ] as [[number, number], [number, number], [number, number], [number, number]],
  /** Raw RGBA bytes (length = width*height*4), base64. */
  rgbaBase64: ``,
} as const;

export function decodeArchitectureCBandCrop(): {
  width: number;
  height: number;
  data: Uint8Array;
  originX: number;
  originY: number;
} {
  const bin =
    typeof Buffer !== "undefined"
      ? Uint8Array.from(Buffer.from(ARCHITECTURE_C_BAND_CROP.rgbaBase64, "base64"))
      : Uint8Array.from(atob(ARCHITECTURE_C_BAND_CROP.rgbaBase64), (c) => c.charCodeAt(0));
  if (bin.length !== ARCHITECTURE_C_BAND_CROP.width * ARCHITECTURE_C_BAND_CROP.height * 4) {
    throw new Error(
      `architectureCStillBandCrop: expected ${ARCHITECTURE_C_BAND_CROP.width * ARCHITECTURE_C_BAND_CROP.height * 4} bytes, got ${bin.length}`,
    );
  }
  return {
    width: ARCHITECTURE_C_BAND_CROP.width,
    height: ARCHITECTURE_C_BAND_CROP.height,
    data: bin,
    originX: ARCHITECTURE_C_BAND_CROP.originX,
    originY: ARCHITECTURE_C_BAND_CROP.originY,
  };
}

/** Embed the crop into a full-frame 720×1280 canvas (outside-crop = cream body). */
export function embedArchitectureCBandCropInFrame(): {
  width: number;
  height: number;
  data: Uint8Array;
} {
  const crop = decodeArchitectureCBandCrop();
  const Wf = ARCHITECTURE_C_BAND_CROP.frameW;
  const Hf = ARCHITECTURE_C_BAND_CROP.frameH;
  const data = new Uint8Array(Wf * Hf * 4);
  for (let i = 0; i < Wf * Hf; i++) {
    data[i * 4] = 200;
    data[i * 4 + 1] = 185;
    data[i * 4 + 2] = 165;
    data[i * 4 + 3] = 255;
  }
  for (let y = 0; y < crop.height; y++) {
    for (let x = 0; x < crop.width; x++) {
      const si = (y * crop.width + x) * 4;
      const di = ((crop.originY + y) * Wf + (crop.originX + x)) * 4;
      data[di] = crop.data[si]!;
      data[di + 1] = crop.data[si + 1]!;
      data[di + 2] = crop.data[si + 2]!;
      data[di + 3] = 255;
    }
  }
  return { width: Wf, height: Hf, data };
}
